#include <iostream>
#include <vector>
using namespace std;

// is_prime[i] is true exactly when i is prime, for 0 <= i <= n.
vector<bool> sieve(int n) {
    vector<bool> is_prime(n + 1, true);
    is_prime[0] = false;
    if (n >= 1) is_prime[1] = false;
    for (long long p = 2; p * p <= n; ++p) {
        if (!is_prime[p]) continue;
        // Smaller multiples of p were crossed out by smaller primes already.
        for (long long m = p * p; m <= n; m += p) is_prime[m] = false;
    }
    return is_prime;
}

int main() {
    const int n = 50;
    vector<bool> is_prime = sieve(n);
    int count = 0;
    cout << "primes up to " << n << ":";
    for (int i = 2; i <= n; ++i) {
        if (is_prime[i]) {
            cout << ' ' << i;
            ++count;
        }
    }
    cout << "\n" << count << " primes\n";

    vector<bool> big = sieve(1000000);
    int total = 0;
    for (bool b : big) total += b;
    cout << "primes up to one million: " << total << "\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

// spf[i] = the smallest prime dividing i, for 2 <= i <= n.
vector<int> smallestPrimeFactors(int n) {
    vector<int> spf(n + 1, 0);
    for (int i = 2; i <= n; ++i) {
        if (spf[i] != 0) continue;  // i already has a smaller prime factor
        for (long long m = i; m <= n; m += i)
            if (spf[m] == 0) spf[m] = i;  // i is prime: claim its unclaimed multiples
    }
    return spf;
}

// Prime factors of x with multiplicity, smallest first, in O(log x).
vector<int> factorize(int x, const vector<int>& spf) {
    vector<int> factors;
    while (x > 1) {
        factors.push_back(spf[x]);
        x /= spf[x];
    }
    return factors;
}

int main() {
    const int n = 1000000;
    vector<int> spf = smallestPrimeFactors(n);
    for (int x : {360, 97, 1024, 123456, 999983}) {
        vector<int> f = factorize(x, spf);
        cout << x << " =";
        for (size_t i = 0; i < f.size(); ++i) cout << (i ? " * " : " ") << f[i];
        cout << "  (" << f.size() << " prime factor" << (f.size() == 1 ? "" : "s") << ")\n";
    }
    return 0;
}

#include <cstdint>
#include <iostream>
using namespace std;

// a^e mod m with O(log e) multiplications (m < 2^32, so products fit in 64 bits).
uint64_t powMod(uint64_t a, uint64_t e, uint64_t m) {
    uint64_t result = 1 % m;
    a %= m;
    while (e > 0) {
        if (e & 1) result = result * a % m;  // this bit of e is set: use the current square
        a = a * a % m;                        // a^(2^k) -> a^(2^(k+1))
        e >>= 1;
    }
    return result;
}

// The same loop on 2x2 matrices: [[1,1],[1,0]]^n = [[F(n+1), F(n)], [F(n), F(n-1)]].
struct Mat { uint64_t a, b, c, d; };

Mat mul(const Mat& x, const Mat& y, uint64_t m) {
    return {(x.a * y.a + x.b * y.c) % m, (x.a * y.b + x.b * y.d) % m,
            (x.c * y.a + x.d * y.c) % m, (x.c * y.b + x.d * y.d) % m};
}

uint64_t fibonacci(uint64_t n, uint64_t m) {
    Mat result{1, 0, 0, 1}, base{1, 1, 1, 0};
    while (n > 0) {
        if (n & 1) result = mul(result, base, m);
        base = mul(base, base, m);
        n >>= 1;
    }
    return result.b;
}

int main() {
    const uint64_t MOD = 1000000007;
    cout << "3^13 mod 1e9+7    = " << powMod(3, 13, MOD) << "\n";
    cout << "2^62 mod 1e9+7    = " << powMod(2, 62, MOD) << "\n";
    cout << "7^(10^18) mod 1e9+7 = " << powMod(7, 1000000000000000000ULL, MOD) << "\n";
    cout << "F(10)             = " << fibonacci(10, MOD) << "\n";
    cout << "F(10^18) mod 1e9+7 = " << fibonacci(1000000000000000000ULL, MOD) << "\n";
    // Ways to climb 45 stairs taking 1 or 2 at a time = F(46) < 2^32, so reducing
    // modulo 2^32 keeps it exact (and every product stays below 2^64).
    cout << "ways to climb 45 stairs = " << fibonacci(46, 1ULL << 32) << "\n";
    return 0;
}

#include <iostream>
using namespace std;

// Returns g = gcd(a, b) and sets x, y so that a*x + b*y = g (a, b >= 0).
long long extendedGcd(long long a, long long b, long long& x, long long& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    long long x1, y1;
    long long g = extendedGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

// The inverse of a modulo m, or -1 when gcd(a, m) != 1 (no inverse exists).
long long modInverse(long long a, long long m) {
    long long x, y;
    long long g = extendedGcd(((a % m) + m) % m, m, x, y);
    if (g != 1) return -1;
    return ((x % m) + m) % m;
}

int main() {
    long long x, y;
    long long g = extendedGcd(240, 46, x, y);
    cout << "gcd(240, 46) = " << g << " = 240*(" << x << ") + 46*(" << y << ")\n";

    cout << "inverse of 3 mod 11  = " << modInverse(3, 11) << "\n";
    cout << "inverse of 10 mod 17 = " << modInverse(10, 17) << "\n";
    cout << "inverse of 6 mod 9   = " << modInverse(6, 9) << "  (gcd is 3: none)\n";

    // 14x = 30 (mod 100): gcd(14, 100) = 2 divides 30, so solve 7x = 15 (mod 50).
    long long inv = modInverse(7, 50);
    cout << "14x = 30 (mod 100)  ->  x = " << (15 * inv) % 50 << " (mod 50)\n";
    return 0;
}
